\begin{definition}[Local von Neumann Algebra]
    \label{def:local-von-neumann}
    \lean{Physicslib4.AQFT.HaagKastler.HaagKastlerNet.localOperators, Physicslib4.AQFT.HaagKastler.HaagKastlerNet.localVonNeumann}
