n40961.content:
\begin{definition}[Vacuum State with the Concrete Spectrum Condition]
    \label{def:vacuum-state-concrete}
    \lean{Physicslib4.AQFT.HaagKastler.CovariantQuasilocalAlgebra.IsVacuumStateConcrete}
