n41016.content:
\begin{theorem}[Geometric Covariance of the von Neumann Net (Curved Spacetime)]
    \label{thrm:von-neumann-geometric-covariance-in-curved-spacetime}
    \lean{Physicslib4.AQFT.HaagKastlerCurved.HaagKastlerNet.lieConj_image_localVonNeumann, Physicslib4.AQFT.HaagKastlerCurved.HaagKastlerNet.lieConj_image_localOperators}
